"""matplotlib.colorizer — colorizer stubs (new in 3.9)."""

from matplotlib.cm import ScalarMappable, get_cmap
from matplotlib.colors import Normalize


class Colorizer:
    def __init__(self, cmap=None, norm=None):
        self.cmap = get_cmap(cmap) if isinstance(cmap, str) else cmap
        self.norm = norm or Normalize()

    def to_rgba(self, x, alpha=None, bytes=False):
        if self.cmap is None:
            self.cmap = get_cmap()
        normed = self.norm(x)
        return self.cmap(normed, alpha=alpha, bytes=bytes)


# ─── Added: missing public names from upstream colorizer.py ────────


class ColorizingArtist:
    """Mixin that gives an artist a :class:`Colorizer` and re-exposes the
    cmap/norm-style accessors used by callers that don't know it's a
    Colorizer underneath."""

    def __init__(self, colorizer=None, **kwargs):
        self._colorizer = colorizer or Colorizer()

    @property
    def colorizer(self):
        return self._colorizer

    @colorizer.setter
    def colorizer(self, c):
        self._colorizer = c

    def get_cmap(self):
        return self._colorizer.cmap

    def set_cmap(self, cmap):
        self._colorizer.cmap = get_cmap(cmap) if isinstance(cmap, str) else cmap

    def get_norm(self):
        return self._colorizer.norm

    def set_norm(self, norm):
        self._colorizer.norm = norm or Normalize()


class _ColorizerInterface(ColorizingArtist):
    """Legacy name kept so isinstance checks against the old name work.
    Equivalent to :class:`ColorizingArtist`."""
    pass


class _ScalarMappableInterface(ScalarMappable):
    """Inherits from :class:`~matplotlib.cm.ScalarMappable`. Provided so
    callers can ``isinstance(art, _ScalarMappableInterface)`` regardless
    of which internal class actually backs the artist."""
    pass


def _auto_norm_from_scale(scale):
    """Return a sensible Normalize for a given scale name. Mirrors upstream's
    helper which picks LogNorm for the log scale, AsinhNorm for asinh, etc.
    """
    if scale == 'log':
        from matplotlib.colors import LogNorm
        return LogNorm()
    if scale == 'symlog':
        from matplotlib.colors import SymLogNorm
        return SymLogNorm(linthresh=1)
    if scale == 'asinh':
        from matplotlib.colors import AsinhNorm
        return AsinhNorm()
    return Normalize()
